import { defineStore } from 'pinia'
import { authRequest, setToken, clearToken } from '../utils/request'
import { aesEncrypt } from '../utils/aes'

export const useAuthStore = defineStore('portal-auth', () => {
  async function login(username: string, password: string, captcha?: { code: string; uuid: string }): Promise<void> {
    const encrypted = aesEncrypt(password)
    const payload: Record<string, string> = { username, password: encrypted }
    if (captcha?.code && captcha.uuid) {
      payload.code = captcha.code
      payload.uuid = captcha.uuid
    }
    const res = await authRequest<{ accessToken?: string; token?: string }>('/v2.0/security/auth/login', {
      method: 'POST',
      data: payload,
      token: false,
      raw: true,
    })
    const body = res as unknown as { code?: number; msg?: string; data?: { accessToken?: string; token?: string } }
    if (body && typeof body === 'object' && 'code' in body && body.code !== 200) throw new Error(body.msg || '登录失败')
    const token = body?.data?.accessToken ?? body?.data?.token
    if (!token) throw new Error('登录失败：未获取到令牌')
    setToken(token)
  }

  function logout(): void {
    clearToken()
  }

  return { login, logout }
})

